#!/usr/bin/env bash
# Regenerates src/Version.php from VERSION (the one source of the fmt version). Run by tools/build.sh.
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
UPSTREAM=3.95.27
ver="$(tr -d '[:space:]' < "$ROOT/VERSION")"
cat > "$ROOT/src/Version.php" <<PHP
<?php

declare(strict_types=1);

namespace Fmt;

// GENERATED by tools/gen-version.sh from VERSION. Do not edit.
final class Version
{
    public const VERSION = '$ver';
    public const UPSTREAM = '$UPSTREAM';
    public const ABOUT = 'Manticore Fmt $ver (rules of PHP CS Fixer $UPSTREAM)';
}
PHP
